          ),
          
          DEFINE = 
            "
STANDARDIZE I2 S2;
wz_int = S2 * edu12; ! WZ
      ",
          
          ANALYSIS =
            "estimator = mlr;
TYPE=COMPLEX;
TYPE = RANDOM;
!type = mixture;
ALGORITHM=INTEGRATION;
!INTEGRATION = MONTECARLO;
!starts = 600 200;
!starts = 20;
!LRTBOOTSTRAP = 200;
!processors = 10;
coverage = 0.005;",
          
          MODEL = 
            "
i1 s1 | wfdms12@0 wfdms16*4 wfdms18*6 wfdms20*8 wfdms22@10;
!i2 s2 | wfdss12@0 wfdss16*4 wfdss18*6 wfdss20*8 wfdss22@10;  
