      pp_lgca_type13_step1 <- readModels(paste0(filepath,"pp_lgca_type13step1.out"), quiet = TRUE)
      pp_lgca_type13_step1.data <- pp_lgca_type13_step1[["savedata"]]
      names(pp_lgca_type13_step1.data)
      
      # 对I3进行标准化
      pp_lgca_type13_step1.data <- pp_lgca_type13_step1.data %>%
        mutate(I3_std = (I3 - mean(I3, na.rm = TRUE))/sd(I3, na.rm = TRUE)) %>%
        mutate(S3_std = (S3 - mean(S3, na.rm = TRUE))/sd(S3, na.rm = TRUE))
      
      # 调节变量取值范围
      wvalue_i3_min <- min(pp_lgca_type13_step1.data$I3_std, na.rm = TRUE)
      wvalue_i3_max <- max(pp_lgca_type13_step1.data$I3_std, na.rm = TRUE)
      
      wvalue_s3_min <- min(pp_lgca_type13_step1.data$S3_std, na.rm = TRUE)
      wvalue_s3_max <- max(pp_lgca_type13_step1.data$S3_std, na.rm = TRUE)
      
      wvalue_i3_min
      wvalue_i3_max
      wvalue_s3_min
      wvalue_s3_max
      
      # 按照pid为索引, 将 pp_lgca_type12_step1.data 的 I2 S2 追加至每个 lgca_covar_MI_tics_data 的插补数据集中
      join_df <- pp_lgca_type13_step1.data %>% select(PID, I3, S3)
      target_names <- names(lgca_covar_MI_tics_data) %>%
        str_subset("^missimp_TICs_catg_conti\\d+\\.dat$")
      
      lgca_covar_MI_tics_data[target_names] <- lapply(
        lgca_covar_MI_tics_data[target_names],
        function(df) left_join(df, join_df, by = "PID")
      )
      
      names(lgca_covar_MI_tics_data[["missimp_TICs_catg_conti10.dat"]])
      
      
      ## step2: treat latent growth factors as observed vars
      # within covar
      ### 性别调节效应
      # i1i3_int
      {
        pp_lgca <- mplusObject( 
          TITLE = glue(
            "Class-1_pp_LGCA"),
          
          VARIABLE = glue(
            "usevar = 
  wfdms12 wfdms16 wfdms18 wfdms20 wfdms22 
!wfdss12 wfdss16 wfdss18 wfdss20 wfdss22
!wfdds12 wfdds16 wfdds18 wfdds20 wfdds22
