!marr20 eco202 eco203 hwc202 hwc203 
!ageg22 pinc22 cores22 heal221 heal223 
!marr22 eco222 eco223 hwc222 hwc223

I3 S3

wz_int ! WZ

;
idvariable=pid;
cluster=fid;"
          ),
          
          DEFINE = 
            "
STANDARDIZE I3 S3;
wz_int = I3 * sex12; ! WZ
      ",
          
          ANALYSIS =
            "estimator = mlr;
TYPE=COMPLEX;
TYPE = RANDOM;
!type = mixture;
