cluster=fid;"
          ),
          
          DEFINE = 
            "
STANDARDIZE I3 S3;
wz_int = s3 * sex12; ! WZ
      ",
          
          ANALYSIS =
            "estimator = mlr;
TYPE=COMPLEX;
TYPE = RANDOM;
!type = mixture;
ALGORITHM=INTEGRATION;
!INTEGRATION = MONTECARLO;
!starts = 600 200;
!starts = 20;
!LRTBOOTSTRAP = 200;
!processors = 10;
coverage = 0.005;",
          
          MODEL = 
            "
i1 s1 | wfdms12@0 wfdms16*4 wfdms18*6 wfdms20*8 wfdms22@10;
!i2 s2 | wfdss12@0 wfdss16*4 wfdss18*6 wfdss20*8 wfdss22@10;  
!i3 s3 | wfdds12@0 wfdds16@4 wfdds18@6 wfdds20@8 wfdds22@10;  
!i4 s4 | wfdds112@0 wfdds116@4 wfdds118@6 wfdds120@8 wfdds122@10;
i5 s5 | ces8sd12@0 ces8sd16*4 ces8sd18*6 ces8sd20*8 ces8sd22@10;  

!s5@0;
![i1](x_mean);
!i1(x_var);

![s1](x_mean);
!s1(x_var);

![i3](w_mean);
!i3(w_var);

[s3](w_mean);
s3(w_var);

!!! correlation among residual error terms of three indicators at each time point
!wfdms12 wfdss12 wfdds12 wfdds112 WITH wfdms12 wfdss12 wfdds12 wfdds112;
!wfdms16 wfdss16 wfdds16 wfdds116 WITH wfdms16 wfdss16 wfdds16 wfdds116;
!wfdms18 wfdss18 wfdds18 wfdds118 WITH wfdms18 wfdss18 wfdds18 wfdds118;
