                                    modelout = glue("pp_lgca_type13_urban12step2_i_mod_i_MI_TICs.inp"),
                                    check = TRUE, run = TRUE, hashfilename = FALSE, quiet = FALSE)  
      } 
      
      # i1s3_int
      {
        pp_lgca <- mplusObject( 
          TITLE = glue(
            "Class-1_pp_LGCA"),
          
          VARIABLE = glue(
            "usevar = 
  wfdms12 wfdms16 wfdms18 wfdms20 wfdms22 
!wfdss12 wfdss16 wfdss18 wfdss20 wfdss22
