wiis1 = b4s + b7s*hi_z;

!!! s on i * s
NEW (wiss0 wiss1);
wiss0 = b4s + b7s*lo_z;
wiss1 = b4s + b7s*hi_z;

!!! s on s * i
NEW (wsis0 wsis1);
wsis0 = b4s + b7s*lo_z;
wsis1 = b4s + b7s*hi_z;
*!
!!! s on s * s
