!ageg20 pinc20 cores20 heal201 heal203 
!marr20 eco202 eco203 hwc202 hwc203 
!ageg22 pinc22 cores22 heal221 heal223 
!marr22 eco222 eco223 hwc222 hwc223

I4 S4

wz_int ! WZ

;
idvariable=pid;
cluster=fid;"
          ),
          
          DEFINE = 
            "
STANDARDIZE I4 S4;
wz_int = S4 * sex12; ! WZ
      ",
          
          ANALYSIS =
            "estimator = mlr;
TYPE=COMPLEX;
TYPE = RANDOM;
!type = mixture;
ALGORITHM=INTEGRATION;
!INTEGRATION = MONTECARLO;
!starts = 600 200;
!starts = 20;
!LRTBOOTSTRAP = 200;
!processors = 10;
coverage = 0.005;",
          
          MODEL = 
            "
i1 s1 | wfdms12@0 wfdms16*4 wfdms18*6 wfdms20*8 wfdms22@10;
!i2 s2 | wfdss12@0 wfdss16*4 wfdss18*6 wfdss20*8 wfdss22@10;  
!i3 s3 | wfdds12@0 wfdds16@4 wfdds18@6 wfdds20@8 wfdds22@10;  
!i4 s4 | wfdds412@0 wfdds416@4 wfdds418@6 wfdds420@8 wfdds422@10;
i5 s5 | ces8sd12@0 ces8sd16*4 ces8sd18*6 ces8sd20*8 ces8sd22@10;  

!s5@0;
![i1](x_mean);
!i1(x_var);

![s1](x_mean);
!s1(x_var);

![i4](w_mean);
!i4(w_var);

[s4](w_mean);
s4(w_var);

!!! correlation among residual error terms of three indicators at each time point
!wfdms12 wfdss12 wfdds12 wfdds412 WITH wfdms12 wfdss12 wfdds12 wfdds412;
!wfdms16 wfdss16 wfdds16 wfdds416 WITH wfdms16 wfdss16 wfdds16 wfdds416;
!wfdms18 wfdss18 wfdds18 wfdds418 WITH wfdms18 wfdss18 wfdds18 wfdds418;
!wfdms20 wfdss20 wfdds20 wfdds420 WITH wfdms20 wfdss20 wfdds20 wfdds420;
!wfdms22 wfdss22 wfdds22 wfdds422 WITH wfdms22 wfdss22 wfdds22 wfdds422;

xw_int | s1 XWITH s4; ! XW
xz_int | s1 XWITH sex12; ! XZ
!wz_int | s4 XWITH sex12; ! WZ
xwz_int | xw_int XWITH sex12; ! XWZ

!!! Focus: intercept of ces8sd regressed on intercept of wfd
!i5 on i1 i4;
i5 on i1(b1i);
