          ),
          
          DEFINE = 
            "
STANDARDIZE I4 S4;
wz_int = S4 * urban12; ! WZ
      ",
          
          ANALYSIS =
            "estimator = mlr;
TYPE=COMPLEX;
TYPE = RANDOM;
!type = mixture;
ALGORITHM=INTEGRATION;
!INTEGRATION = MONTECARLO;
