        pp_lgca_fit <- mplusModeler(pp_lgca, 
                                    dataout = "pp_lgca_type14_4_urban12step2_s_mod_i_MI_TICs.dat", 
                                    modelout = glue("pp_lgca_type14_4_urban12step2_s_mod_i_MI_TICs.inp"),
                                    check = TRUE, run = TRUE, hashfilename = FALSE, quiet = FALSE)  
      } 
      
      # s1i4_int
      {
        pp_lgca <- mplusObject( 
          TITLE = glue(
            "Class-1_pp_LGCA"),
          
          VARIABLE = glue(
            "usevar = 
  wfdms12 wfdms16 wfdms18 wfdms20 wfdms22 
!wfdss12 wfdss16 wfdss18 wfdss20 wfdss22
!wfdds12 wfdds16 wfdds18 wfdds20 wfdds22
!wfdds412 wfdds416 wfdds418 wfdds420 wfdds422
ces8sd12 ces8sd16 ces8sd18 ces8sd20 ces8sd22

!!! time-invar
sex12 edu12 urban12 
prov122 prov123 
cdn12 cdar12 
cdsc121  
minor12 wave  

!!! time-var
ageg12 pinc12 pinc212 cores12 heal121 heal123 
marr12 eco122 eco123 hwc122 hwc123 hukou12 sat12 adl12 finc12 
!ageg14 pinc14 cores14 heal141 heal143 
!marr14 										    
!ageg16 pinc16 cores16 heal161 heal163 
!marr16 eco162 eco163 hwc162 hwc163 
!ageg18 pinc18 cores18 heal181 heal183 
!marr18 eco182 eco183 hwc182 hwc183 
