            # predictor.var %in% c("S1SX_INT","S2SX_INT","S3SX_INT","S4SX_INT") ~ "SEX × Slope",
            predictor.var == "Intercepts" ~ "Means",
            predictor.var == "Residual.Variances" ~ "Variances",
