wz_int = s1 * sex12; ! WZ
      ",
          
          ANALYSIS =
            "estimator = mlr;
TYPE=COMPLEX;
TYPE = RANDOM;
!type = mixture;
ALGORITHM=INTEGRATION;
!INTEGRATION = MONTECARLO;
