wiss1 = b4s + b7s*hi_z;

!!! s on s * i
NEW (wsis0 wsis1);
wsis0 = b4s + b7s*lo_z;
wsis1 = b4s + b7s*hi_z;
*!
!!! s on s * s
NEW (wsss0 wsss1);
