!  = iY + (b1 + b5Z) * X + (b4 + b7Z) W * X + b2W + b3Z + b6WZ + eY

! Range of W value
!
! min_wi = ({wvalue_i1_min})   max_wi = ({wvalue_i1_max})
! min_ws = ({wvalue_s1_min})   max_ws = ({wvalue_s1_max})

NEW( min_w lo_w med_w hi_w max_w lo_z hi_z );

min_w = ({wvalue_i1_min});
lo_w = w_mean - sqrt(w_var);   ! -1 SD below mean of W
med_w = w_mean;   ! mean of W
hi_w = w_mean + sqrt(w_var);   ! +1 SD below mean of W
max_w = ({wvalue_i1_max});

lo_z = 0;   ! low of Z
hi_z = 1;   ! high of Z

       

!!!!! XW_int→Y = (b4 + b7Z) W * X
!*
!!! i on i * i
NEW (wiii0 wiii1);
wiii0 = b4i + b7i*lo_z;
wiii1 = b4i + b7i*hi_z;

!!! s on i * i
NEW (wiis0 wiis1);
wiis0 = b4s + b7s*lo_z;
wiis1 = b4s + b7s*hi_z;

!!! s on i * s
NEW (wiss0 wiss1);
wiss0 = b4s + b7s*lo_z;
wiss1 = b4s + b7s*hi_z;
*!
