        pp_lgca_fit <- mplusModeler(pp_lgca, 
                                    dataout = "pp_lgca_type4_41_urban12step2_i_mod_i_MI_TICs.dat", 
                                    modelout = glue("pp_lgca_type4_41_urban12step2_i_mod_i_MI_TICs.inp"),
                                    check = TRUE, run = TRUE, hashfilename = FALSE, quiet = FALSE)  
      } 
      
