NEW (wiii0 wiii1);
wiii0 = b4i + b7i*lo_z;
wiii1 = b4i + b7i*hi_z;

!!! s on i * i
NEW (wiis0 wiis1);
wiis0 = b4s + b7s*lo_z;
wiis1 = b4s + b7s*hi_z;

!!! s on i * s
NEW (wiss0 wiss1);
wiss0 = b4s + b7s*lo_z;
wiss1 = b4s + b7s*hi_z;

!!! s on s * i
NEW (wsis0 wsis1);
wsis0 = b4s + b7s*lo_z;
wsis1 = b4s + b7s*hi_z;
*!
!!! s on s * s
NEW (wsss0 wsss1);
wsss0 = b4s + b7s*lo_z;
wsss1 = b4s + b7s*hi_z;


!!!!! X→Y = (b1 + b4W + b5Z + b7WZ)*X
!*
