          predictor.var = "Model fit index",
          I5.ON = model.fit_text.type1,
          S5.ON = model.fit_text.type1
        ) %>% 
        mutate(
          predictor.var.common = case_when(
            # predictor.var %in% c("I1", "I2", "I3", "I4") ~ "Intercept",
